            <tr><td className="px-3 py-2 text-xs">2位</td><td className="px-3 py-2 text-xs">福島県</td><td className="px-3 py-2 text-xs">78件</td><td className="px-3 py-2 text-xs">道路横断や住宅地周辺での目撃事案</td></tr>
